import { spawnSync } from 'node:child_process'
import { performance } from 'node:perf_hooks'

const samples = []
for (let index = 0; index < 5; index += 1) {
  const start = performance.now()
  const child = spawnSync(process.execPath, ['--expose-gc', 'worker.mjs'], {
    cwd: import.meta.dirname,
    encoding: 'utf8',
  })
  const wallMs = performance.now() - start
  if (child.status !== 0) throw new Error(child.stderr || `worker exited ${child.status}`)
  samples.push({
    wallMs: Number(wallMs.toFixed(3)),
    ...JSON.parse(child.stdout),
  })
}

console.log(
  JSON.stringify(
    {
      clock: 'parent performance.now around child process start, module import, batches and exit',
      state: 'fresh child process for each sample; no cross-sample warm cache',
      samples,
    },
    null,
    2,
  ),
)

const retained = new Map()
const retainedBytesPerBatch = 32 * 1024

function classify(row) {
  return row.kind === 'priority' ? 'urgent' : 'standard'
}

export function processBatch(batch) {
  const parsed = batch.rows.map((row, index) => ({
    id: `${batch.id}-${index}`,
    amount: row.amount,
    kind: classify(row),
  }))

  const summary = parsed.reduce(
    (result, row) => {
      result.count += 1
      result.total += row.amount
      result[row.kind] += 1
      return result
    },
    { count: 0, total: 0, urgent: 0, standard: 0 },
  )

  const payload = Buffer.allocUnsafeSlow(retainedBytesPerBatch)
  payload.fill(0)
  retained.set(batch.id, { payload, summary })
  return { ...summary }
}

export function retainedBatches() {
  return retained.size
}

export function releaseRetainedBatches() {
  retained.clear()
}
import { processBatch, releaseRetainedBatches, retainedBatches } from './src/session.mjs'

function memorySnapshot() {
  if (typeof global.gc === 'function') global.gc({ type: 'major', execution: 'sync' })
  return process.memoryUsage()
}

const before = memorySnapshot()
let last
for (let batchIndex = 0; batchIndex < 30; batchIndex += 1) {
  const rows = Array.from({ length: 2_000 }, (_, rowIndex) => ({
    amount: (rowIndex + batchIndex) % 97,
    kind: rowIndex % 11 === 0 ? 'priority' : 'standard',
  }))
  last = processBatch({ id: `batch-${batchIndex}`, rows })
}
const retained = memorySnapshot()
const retainedBatchesCount = retainedBatches()
releaseRetainedBatches()
const released = memorySnapshot()

console.log(
  JSON.stringify({
    result: last,
    retainedBatches: retainedBatchesCount,
    heapDeltaBytes: retained.heapUsed - before.heapUsed,
    retainedArrayBufferDeltaBytes: retained.arrayBuffers - before.arrayBuffers,
    gc: typeof global.gc === 'function' ? 'explicit synchronous major global.gc before each sample' : 'unavailable',
    negativeControl: {
      retainedBatches: retainedBatches(),
      arrayBufferDeltaBytes: released.arrayBuffers - before.arrayBuffers,
    },
  }),
)

import assert from 'node:assert/strict'
import { test } from 'node:test'
import { processBatch, releaseRetainedBatches, retainedBatches } from '../src/session.mjs'

test('batch processing returns a deterministic summary and release clears retained state', () => {
  const result = processBatch({
    id: 'test',
    rows: [
      { amount: 4, kind: 'priority' },
      { amount: 6, kind: 'standard' },
    ],
  })
  assert.deepEqual(result, { count: 2, total: 10, urgent: 1, standard: 1 })
  assert.equal(retainedBatches(), 1)
  releaseRetainedBatches()
  assert.equal(retainedBatches(), 0)
})

