import { processBatch, releaseRetainedBatches, retainedBatches } from './src/session.mjs'

const FIELDS = ['rss', 'heapUsed', 'external', 'arrayBuffers']

function gcMajor() {
  global.gc({ type: 'major', execution: 'sync' })
}

function snapshot() {
  const memory = process.memoryUsage()
  return Object.fromEntries(FIELDS.map((field) => [field, memory[field]]))
}

function delta(after, before) {
  return Object.fromEntries(FIELDS.map((field) => [field, after[field] - before[field]]))
}

function makeRows(batchIndex) {
  return Array.from({ length: 2_000 }, (_, rowIndex) => ({
    amount: (rowIndex + batchIndex) % 97,
    kind: rowIndex % 11 === 0 ? 'priority' : 'standard',
  }))
}

function runOne(id, batchIndex) {
  const rows = makeRows(batchIndex)
  return processBatch({ id, rows })
}

releaseRetainedBatches()
gcMajor()
runOne('warmup', 0)
releaseRetainedBatches()
gcMajor()

const trials = []
let result
for (let trial = 0; trial < 5; trial += 1) {
  releaseRetainedBatches()
  gcMajor()
  const baseline = snapshot()

  result = runOne("'`memory-${trial}`, trial)
  const immediate = snapshot()
  gcMajor()
  const reachableAfterGc = snapshot()
  const retainedCountBeforeRelease = retainedBatches()

  releaseRetainedBatches()
  gcMajor()
  const afterReleaseGc = snapshot()

  trials.push({
    trial,
    retainedCountBeforeRelease,
    retainedCountAfterRelease: retainedBatches(),
    immediateDeltaBytes: delta(immediate, baseline),
    reachableAfterGcDeltaBytes: delta(reachableAfterGc, baseline),
    afterReleaseGcDeltaBytes: delta(afterReleaseGc, baseline),
  })
}

console.log(JSON.stringify({
  sampling: '"'synchronous major GC immediately before baseline and before each post-GC snapshot; immediate snapshot intentionally taken before GC',
  workload: 'one batch of 2,000 fixed rows per trial; one untimed warm-up batch before all trials',
  result,
  trials,
}, null, 2))
NODE"

