import { processBatch, releaseRetainedBatches, retainedBatches } from './src/session.mjs'

const FIELDS = ['rss', 'heapUsed', 'external', 'arrayBuffers']
const checkpoints = [0, 1, 5, 10, 20, 30]

function gcMajor() {
  global.gc({ type: 'major', execution: 'sync' })
}

function snapshot() {
  const memory = process.memoryUsage()
  return Object.fromEntries(FIELDS.map((field) => [field, memory[field]]))
}

function makeRows(batchIndex) {
  return Array.from({ length: 2_000 }, (_, rowIndex) => ({
    amount: (rowIndex + batchIndex) % 97,
    kind: rowIndex % 11 === 0 ? 'priority' : 'standard',
  }))
}

function delta(after, before) {
  return Object.fromEntries(FIELDS.map((field) => [field, after[field] - before[field]]))
}

releaseRetainedBatches()
gcMajor()
processBatch({ id: 'warmup', rows: makeRows(0) })
releaseRetainedBatches()
gcMajor()
const baseline = snapshot()
const beforeRelease = []

for (let batchIndex = 1; batchIndex <= 30; batchIndex += 1) {
  processBatch({ id: "'`scale-${batchIndex}`, rows: makeRows(batchIndex) })
  if (checkpoints.includes(batchIndex)) {
    gcMajor()
    beforeRelease.push({
      batches: retainedBatches(),
      deltaBytes: delta(snapshot(), baseline),
    })
  }
}

releaseRetainedBatches()
gcMajor()
const afterRelease = {
  batches: retainedBatches(),
  deltaBytes: delta(snapshot(), baseline),
}

console.log(JSON.stringify({
  sampling: '"'explicit synchronous major GC before each reported check'; 
    'checkpoint; one warm-up batch was processed, released, then collected before baseline',
  beforeRelease,
  afterRelease,
}, null, 2))
NODE"

